def how_many_times(string: str, substring: str) -> int:
    count = 0
    start = 0
    while True:
        start = string.find(substring, start)
        if start == -1:
            return count
        count += 1
        start += 1

import math

def poly(xs: list, x: float):
    """
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
    """
    return sum([coeff * math.pow(x, i) for i, coeff in enumerate(xs)])

def find_zero(xs: list):
    """ xs are coefficients of a polynomial.
    find_zero find x such that poly(x) = 0.
    find_zero returns only one zero point, even if there are many.
    Moreover, find_zero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> round(find_zero([1, 2]), 2) # f(x) = 1 + 2x
    -0.5
    >>> round(find_zero([-6, 11, -6, 1]), 2) # (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
    """
    def evaluate_polynomial(coefficients, x):
        return sum(coef * x**i for i, coef in enumerate(coefficients))

    def derivative(coefficients, x):
        return sum(i * coef * x**(i-1) for i, coef in enumerate(coefficients) if i > 0)

    def newton_raphson(coefficients, x0, tol=1e-10, max_iter=1000):
        for _ in range(max_iter):
            fx = evaluate_polynomial(coefficients, x0)
            dfx = derivative(coefficients, x0)
            if abs(dfx) < tol:
                raise ValueError("Derivative too small; no convergence possible.")
            x1 = x0 - fx / dfx
            if abs(x1 - x0) < tol:
                return x1
            x0 = x1
        raise ValueError("Maximum iterations reached; no convergence.")

    if len(xs) % 2 != 0 or xs[-1] == 0:
        raise ValueError("List must have an even number of coefficients and a non-zero leading coefficient.")

    return newton_raphson(xs, 0.0)

