def correct_bracketing(brackets: str) -> bool:
    stack = []
    for bracket in brackets:
        if bracket == '<':
            stack.append(bracket)
        elif bracket == '>':
            if not stack or stack[-1] != '<':
                return False
            stack.pop()
    return len(stack) == 0

from typing import List

def derivative(xs: List[int]) -> List[int]:
    return [i * coeff for i, coeff in enumerate(xs)][1:]

def strange_sort_list(lst):
    sorted_lst = sorted(lst)
    result = []
    while sorted_lst:
        if sorted_lst:
            result.append(sorted_lst.pop(0))
        if sorted_lst:
            result.append(sorted_lst.pop())
    return result

def smallest_change(arr):
    left = 0
    right = len(arr) - 1
    changes = 0

    while left < right:
        if arr[left] != arr[right]:
            changes += 1
        left += 1
        right -= 1

    return changes

import math

def is_simple_power(x, n):
    if n == 1:
        return x == 1
    power = int(math.log(x, n))
    return n ** power == x

def decimal_to_binary(decimal):
    if decimal == 0:
        return "db0db"
    binary = ""
    while decimal > 0:
        binary = str(decimal % 2) + binary
        decimal //= 2
    return "db" + binary + "db"

import math

def prime_length(string):
    n = len(string)
    if n <= 1:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def anti_shuffle(s):
    words = s.split()
    ordered_words = [''.join(sorted(word)) for word in words]
    return ' '.join(ordered_words)

def encrypt(s):
    result = []
    for char in s:
        if char.isalpha():
            shift = (2 * 2) % 26  # Rotate by 4 positions
            if char.islower():
                start = ord('a')
            else:
                start = ord('A')
            encrypted_char = chr(start + (ord(char) - start + shift) % 26)
            result.append(encrypted_char)
        else:
            result.append(char)
    return ''.join(result)

from math import sqrt

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def skjkasdkd(lst):
    max_prime = 0
    for num in lst:
        if num > max_prime and is_prime(num):
            max_prime = num

    return sum(int(digit) for digit in str(max_prime))

